/*
 * A285599  1-limiting word of the morphism 0->11, 1-> 0111.
 * https://oeis.org/A285599
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence generated by iterating the morphism
 *   f: 0 → 11 , 1 → 0111
 * from the seed‑word 0 and keeping only the odd iterations.
 * The returned value is the n‑th bit (0‑based) of the resulting infinite word.
 * The function works for any offset n ≥ 1, even if calls are out of order. */
#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n) {
    if (n == 0) return 0;                    /* offset is 1; behaviour below does not matter */
    size_t target = (size_t)n;

    /* start with the first odd iteration word: w1 = f(0) = "11" */
    size_t len = 2;
    uint8_t *w = (uint8_t*)malloc(len);
    if (!w) return 0;                        /* allocation failure safety */
    w[0] = w[1] = 1;

    while (len < target) {
        /* apply f twice to each symbol of w to obtain the next odd iteration word */
        size_t max_len = len * 18;            /* 18 is the maximum length gained from a single symbol */
        uint8_t *nw = (uint8_t*)malloc(max_len);
        if (!nw) { free(w); return 0; }

        size_t pos = 0;
        for (size_t i = 0; i < len; ++i) {
            uint8_t c = w[i];
            if (c == 0) {                     /* f(0) = 11 → each 1 → 0111 → 01110111 (8 chars) */
                /* 0 → 11 → each 1 expands to 0111 */
                nw[pos++] = 0; nw[pos++] = 1; nw[pos++] = 1; nw[pos++] = 1;
                nw[pos++] = 0; nw[pos++] = 1; nw[pos++] = 1; nw[pos++] = 1;
            } else {                          /* f(1) = 0111 → each 0→11, each 1→0111 → 110111011101110111 (18 chars) */
                /* 0 → 11 */
                nw[pos++] = 1; nw[pos++] = 1;
                /* 1 → 0111 */
                nw[pos++] = 0; nw[pos++] = 1; nw[pos++] = 1; nw[pos++] = 1;
                /* 1 → 0111 */
                nw[pos++] = 0; nw[pos++] = 1; nw[pos++] = 1; nw[pos++] = 1;
                /* 1 → 0111 */
                nw[pos++] = 0; nw[pos++] = 1; nw[pos++] = 1; nw[pos++] = 1;
            }
        }
        free(w);
        w = nw;
        len = pos;
    }

    uint8_t bit = w[target - 1];
    free(w);
    return (seq_t)bit;
}
